<script setup>
import { ref, computed, onMounted, onUnmounted, watch, nextTick } from 'vue'
import Icon from './components/Icon.vue'
import ProjectOverview from './components/ProjectOverview.vue'
import RecordPanel from './components/RecordPanel.vue'
import WritingEditor from './components/WritingEditor.vue'
import SubmissionChecklist from './components/SubmissionChecklist.vue'
import { api, operationID, download } from './lib/api'
import { nav } from './lib/schema'

const data=ref(null), projects=ref([]), current=ref(''), view=ref('overview'), loading=ref(true), error=ref(''), busy=ref(false), toast=ref(''), modal=ref(''), modalError=ref(''), form=ref({}), search=ref(''), section=ref('introduction'), editor=ref(''), editorRevision=ref(0), conflict=ref(null), archived=ref(false), libraryRows=ref([]), libraryQuery=ref(''), libraryBusy=ref(false), modalEl=ref(null)
let saveRequest='', toastTimer, pollTimer, focusReturn, refreshing=false
const currentNav=computed(()=>nav.find(n=>n.id===view.value)||nav[0])
const draft=computed(()=>data.value?.drafts.find(d=>d.section===section.value))
const dirty=computed(()=>editor.value!==(draft.value?.content||''))
const reports=computed(()=>{const seen=new Set();return (data.value?.chapter_reviews||[]).filter(r=>{if(seen.has(r.section))return false;seen.add(r.section);return true}).map(r=>({...r,revision:data.value.draft_versions.find(v=>v.id===r.draft_version_id)?.revision||0}))})
const pending=computed(()=>reports.value.reduce((n,r)=>n+r.issues.length-r.resolved.length,0))
const history=computed(()=>(data.value?.draft_versions||[]).filter(v=>v.section===section.value))
const sections=computed(()=>data.value?.sections||[])
const searchResults=computed(()=>[...nav.map(n=>({label:n.label,kind:'功能',run:()=>go(n.id)})),...sections.value.map(s=>({label:s.title,kind:'章节',run:()=>write(s.id)})),...(data.value?.reading_cards||[]).map(p=>({label:p.title,kind:'文献',run:()=>go('library')}))].filter(x=>x.label.includes(search.value)).slice(0,12))
function notify(text){toast.value=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',4500)}
function recoveryKey(){return 'research-unsaved-'+current.value+'-'+section.value}
function setEditorFromData(){editor.value=draft.value?.content||'';editorRevision.value=draft.value?.revision||0;saveRequest='';try{const recovery=JSON.parse(localStorage.getItem(recoveryKey())||'null');if(recovery&&recovery.content!==editor.value){editor.value=recovery.content;editorRevision.value=recovery.revision;notify('已恢复此设备尚未同步的编辑，请核对后保存。')}}catch{}}
function changed(value){editor.value=value;saveRequest='';try{localStorage.setItem(recoveryKey(),JSON.stringify({content:value,revision:editorRevision.value}))}catch{}}
async function refresh(){if(!current.value)return;data.value=await api('projects/'+current.value)}
async function retryLoad(){try{if(data.value){await refresh();error.value=''}else await load()}catch(e){error.value=e.message}}
async function load(pid){loading.value=true;error.value='';try{projects.value=await api('projects');current.value=pid||projects.value[0]?.id||'';if(current.value){await refresh();if(!sections.value.some(s=>s.id===section.value))section.value=sections.value[0]?.id;setEditorFromData()}else{data.value=null;editor.value='';editorRevision.value=0}}catch(e){error.value=e.message}finally{loading.value=false}}
async function save(mode='drafts'){
  if(busy.value)return false;busy.value=true;error.value='';saveRequest||=operationID()
  try{const r=await api('projects/'+current.value+'/'+mode,{section:section.value,content:editor.value,revision:editorRevision.value,request_id:saveRequest});editorRevision.value=r.version.revision;try{localStorage.removeItem(recoveryKey())}catch{}saveRequest='';await refresh();notify(mode==='ai-review'?'AI 评审已提交，关闭页面后仍会继续。':mode==='chapter-review'?'规则检查已完成。':'草稿已保存到服务器。');return true}catch(e){if(e.status===409){conflict.value=e.current;modal.value='conflict'}else error.value=e.message;return false}finally{busy.value=false}
}
async function ensureSaved(){return !dirty.value||await save()}
async function go(id){if(!await ensureSaved())return;view.value=id;modal.value='';window.scrollTo({top:0,behavior:'instant'})}
async function write(id){if(!await ensureSaved())return;section.value=id||section.value;setEditorFromData();view.value='writing';modal.value='';window.scrollTo({top:0,behavior:'instant'})}
async function selectProject(id){if(!await ensureSaved())return;await load(id);modal.value='';view.value='overview'}
async function saveRecord(kind, values){await api('projects/'+current.value+'/'+kind,values);await refresh();notify('记录已保存。')}
async function resolve(report,index){try{await api('projects/'+current.value+'/review-resolution',{id:report.id,issue_index:index,resolved:!report.resolved.includes(index)});await refresh()}catch(e){error.value=e.message}}
async function setStage(stage){try{await api('projects/'+current.value+'/stage',{stage});await refresh()}catch(e){error.value=e.message}}
function openModal(name){modalError.value='';form.value=name==='settings'?{title:data.value.project.title,field:data.value.project.field}:{};modal.value=name}
async function submitProject(){if(modal.value==='new'&&!await ensureSaved())return;busy.value=true;modalError.value='';try{if(modal.value==='new'){const r=await api('projects',form.value);await load(r.id)}else{await api('projects/'+current.value+'/meta',form.value);await refresh();projects.value=await api('projects')}modal.value='';notify('项目信息已保存。')}catch(e){modalError.value=e.message}finally{busy.value=false}}
async function listProjects(){try{projects.value=await api('projects'+(archived.value?'?archived=1':''))}catch(e){modalError.value=e.message}}
async function archiveProject(id,value){if(id===current.value&&!await ensureSaved())return;try{await api('projects/'+id+'/archive',{archived:value});await listProjects();notify(value?'项目已归档，可从归档列表恢复。':'项目已恢复。');if(id===current.value&&value)await load()}catch(e){modalError.value=e.message}}
async function searchLibrary(){libraryBusy.value=true;modalError.value='';try{const r=await api('library?q='+encodeURIComponent(libraryQuery.value));libraryRows.value=Array.isArray(r)?r:r.materials||[]}catch(e){modalError.value=e.message}finally{libraryBusy.value=false}}
async function importMaterial(row){libraryBusy.value=true;modalError.value='';try{const m=await api('library/'+row.id);await saveRecord('reading_cards',{title:m.title,source:(m.sources||[]).map(s=>s.doi||s.url).join('\n'),question:(m.claims||[]).filter(c=>c.field==='question').map(c=>c.text).join('\n'),method:(m.claims||[]).filter(c=>c.field==='method').map(c=>c.text).join('\n'),evidence:(m.claims||[]).filter(c=>c.field==='evidence').map(c=>c.text).join('\n'),limitation:(m.missing||[]).join('\n'),transfer:m.summary||m.text||''});notify('资料已导入为阅读卡片。');modal.value=''}catch(e){modalError.value=e.message}finally{libraryBusy.value=false}}
async function exportProject(){try{download(await api('projects/'+current.value+'/export'),data.value.project.title+'.json')}catch(e){error.value=e.message}}
async function restoreVersion(v){if(!await ensureSaved())return;changed(v.content);modal.value='';notify('历史内容已放入编辑区，保存后会新增版本。')}
async function resolveConflict(useServer){if(useServer){await refresh();editor.value=conflict.value.content;editorRevision.value=conflict.value.revision;try{localStorage.removeItem(recoveryKey())}catch{}modal.value=''}else{editorRevision.value=conflict.value.revision;saveRequest='';modal.value='';await save()}}
function keydown(e){if((e.ctrlKey||e.metaKey)&&e.key==='s'&&view.value==='writing'){e.preventDefault();save()}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();modal.value='search'}if(e.key==='Escape')modal.value='';if(e.key==='Tab'&&modal.value){const list=[...modalEl.value.querySelectorAll('button,input,select,textarea,summary,[tabindex="0"]')].filter(x=>!x.disabled&&x.getClientRects().length);if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0]?.focus()}}}
function unload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
watch(modal,async(n,old)=>{document.body.style.overflow=n?'hidden':'';if(n){if(!old)focusReturn=document.activeElement;await nextTick();(modalEl.value?.querySelector('input,textarea')||modalEl.value?.querySelector('button'))?.focus()}else focusReturn?.focus()})
onMounted(()=>{load();window.addEventListener('keydown',keydown);window.addEventListener('beforeunload',unload);pollTimer=setInterval(async()=>{if(refreshing||busy.value||!data.value?.ai_reviews.some(j=>['creating','queued','running'].includes(j.state)))return;refreshing=true;try{await refresh()}catch{}finally{refreshing=false}},10000)})
onUnmounted(()=>{clearInterval(pollTimer);clearTimeout(toastTimer);window.removeEventListener('keydown',keydown);window.removeEventListener('beforeunload',unload)})
</script>

<template>
<div class="workspace">
  <aside class="sidebar"><a class="brand" href="#" @click.prevent="go('overview')"><span class="brand-symbol"><i></i><i></i><i></i></span><span>研序<small>RESEARCH STUDIO</small></span></a><button class="project-switch" @click="archived=false;listProjects();openModal('projects')"><span class="project-monogram">研</span><span><b>{{data?.project.title||'选择研究项目'}}</b><small>服务器研究空间</small></span><Icon name="down" :size="15"/></button><nav class="side-nav" aria-label="主要导航"><button v-for="n in nav" :key="n.id" :class="{active:view===n.id}" @click="go(n.id)"><Icon :name="n.icon"/><span>{{n.label}}</span><span v-if="n.id==='reviews'&&pending" class="nav-count">{{pending}}</span></button></nav><div class="sidebar-bottom"><div class="project-stage"><span class="status-dot"></span><span>当前阶段<b>{{data?.stages[data.project.stage-1]||'载入中'}}</b></span></div><button class="quiet side-help" @click="openModal('settings')"><Icon name="settings" :size="17"/>项目设置与导出</button></div></aside>
  <main class="main-area"><header class="topbar"><div class="breadcrumb"><span class="desktop-only">我的研究空间</span><Icon name="chevron" class="desktop-only" :size="13"/><b>{{currentNav.label}}</b></div><div class="topbar-actions"><span class="live-badge">服务器同步</span><button class="search-trigger" @click="modal='search'"><Icon name="search" :size="16"/>搜索论文、章节…<kbd>Ctrl K</kbd></button><button class="mobile-search icon-button" aria-label="搜索论文和章节" @click="modal='search'"><Icon name="search"/></button></div></header>
  <div v-if="loading" class="page"><div class="panel empty-state"><Icon name="clock" :size="32"/><h2>正在载入研究空间…</h2></div></div>
  <section v-else class="page" :class="{'writing-page':view==='writing','overview-page':view==='overview'}"><p v-if="error" class="error-message global-error" role="alert">{{error}}<button class="text-button" @click="retryLoad()">重试</button></p><div v-if="!data" class="panel empty-state"><h2>开始一个研究项目</h2><button class="button primary" @click="openModal('new')">新建项目</button></div>
  <template v-else><div class="page-heading"><div><div class="eyebrow">RESEARCH <span></span>{{data.project.field||'填写你的研究方向'}}</div><h1>{{view==='overview'?data.project.title:view==='writing'?'让论证落到纸面':currentNav.label}}</h1><p class="page-description">{{view==='overview'?'从一个好问题开始，让每一条论证都有依据。':data.project.title}}</p></div><button v-if="view==='overview'" class="button primary" @click="write()"><Icon name="pen" :size="17"/>继续写作<Icon name="arrow" :size="17"/></button><button v-if="view==='library'" class="button" @click="openModal('library');libraryRows=[]"><Icon name="book" :size="17"/>从资料库导入</button></div>
  <ProjectOverview v-if="view==='overview'" :data="data" :reports="reports" @go="go" @write="write" @stage="setStage"/>
  <RecordPanel v-else-if="view==='library'" kind="reading_cards" :records="data.reading_cards" :save="saveRecord"/>
  <div v-else-if="view==='ideas'" class="research-modules"><RecordPanel kind="problems" :records="data.problems" :save="saveRecord"/><RecordPanel kind="hypotheses" :records="data.hypotheses" :save="saveRecord"/></div>
  <RecordPanel v-else-if="['experiments','claims','members'].includes(view)" :key="view" :kind="view" :records="data[view]" :save="saveRecord"/>
  <WritingEditor v-else-if="view==='writing'" :sections="sections" :section="section" :content="editor" :revision="editorRevision" :dirty="dirty" :busy="busy" :reports="reports" :jobs="data.ai_reviews" @update:content="changed" @select="write" @save="save()" @history="modal='history'" @rule="save('chapter-review')" @ai="save('ai-review')" @resolve="resolve"/>
  <div v-else-if="view==='reviews'" class="research-modules"><section><div class="panel-heading"><h2>章节检查记录</h2><span class="muted">保留原稿版本，点击继续修订</span></div><article v-for="r in data.chapter_reviews" :key="r.id" class="panel review-full-card"><div class="review-full-meta"><span class="tag" :class="r.source==='ai'?'green':'muted-tag'">{{r.source==='ai'?'AI 评审':'规则检查'}}</span><span>{{sections.find(s=>s.id===r.section)?.title}} · {{r.created_at}}</span></div><h2>{{r.summary}}</h2><p>{{r.issues.length}} 条意见 · {{r.score}}/100</p><button class="button" @click="write(r.section)">定位章节<Icon name="arrow" :size="16"/></button></article><div v-if="!data.chapter_reviews.length" class="panel empty-state"><p>先保存一个章节，再运行规则检查或 AI 评审。</p><button class="button" @click="write()">进入写作</button></div></section><RecordPanel kind="reviews" :records="data.reviews" :save="saveRecord"/></div>
  <SubmissionChecklist v-else-if="view==='submission'" :key="current" :records="data.submission_checks" :save="saveRecord"/>
  <p class="demo-footer actual-footer">{{data.project.title}} · 数据保存在校园服务器</p></template></section></main>
  <nav class="mobile-nav" aria-label="手机底部导航"><button :class="{active:view==='overview'}" @click="go('overview')"><Icon name="grid"/>总览</button><button :class="{active:view==='library'}" @click="go('library')"><Icon name="book"/>文献</button><button :class="{active:view==='writing'}" @click="write()"><Icon name="pen"/>写作</button><button :class="{active:view==='reviews'}" @click="go('reviews')"><Icon name="review"/>评审</button><button @click="modal='more'"><Icon name="menu"/>更多</button></nav>
  <div v-if="toast" class="toast-message" role="status"><Icon name="check" :size="17"/>{{toast}}</div>
  <div v-if="modal" class="modal-backdrop" @click.self="modal=''"><section class="modal panel" ref="modalEl" role="dialog" aria-modal="true" aria-label="研究空间操作"><button class="modal-close icon-button" aria-label="关闭窗口" @click="modal=''"><Icon name="close"/></button>
    <template v-if="modal==='search'"><span class="section-label">快速找到</span><h2>论文、章节与功能</h2><label class="modal-search"><Icon name="search"/><input v-model="search" aria-label="全局搜索关键词" placeholder="例如：方法、实验、文献…"></label><div class="search-results"><button v-for="r in searchResults" :key="r.kind+r.label" @click="r.run()"><span><b>{{r.label}}</b><small>{{r.kind}}</small></span><Icon name="arrow" :size="17"/></button><p v-if="!searchResults.length" class="muted">没有匹配结果，试试其他关键词。</p></div></template>
    <template v-else-if="modal==='history'"><span class="section-label">服务器版本记录</span><h2>{{sections.find(s=>s.id===section)?.title}} · 写作历史</h2><details v-for="v in history" :key="v.id" class="version-item"><summary>v{{v.revision}} · {{v.created_at}} · {{v.source==='manual'?'手动保存':'评审快照'}}</summary><pre>{{v.content}}</pre><button class="button" @click="restoreVersion(v)">放入编辑区</button></details><p v-if="!history.length" class="muted">保存后，版本历史会出现在这里。</p></template>
    <template v-else-if="modal==='conflict'"><span class="section-label">发现更新的服务器版本</span><h2>比较后再保存</h2><p>你的内容仍保留在编辑区。服务器已有 v{{conflict.revision}}：</p><pre class="conflict-content">{{conflict.content}}</pre><button class="button" @click="resolveConflict(true)">使用服务器版本</button><button class="button primary" @click="resolveConflict(false)">保留我的编辑并保存新版本</button></template>
    <template v-else-if="modal==='projects'"><h2>研究项目</h2><div class="heading-actions"><button class="button primary" @click="openModal('new')">新建项目</button><button class="button" @click="archived=!archived;listProjects()">{{archived?'查看进行中项目':'查看归档项目'}}</button></div><div class="search-results"><div v-for="p in projects" :key="p.id" class="project-row"><button :disabled="!!p.archived" @click="selectProject(p.id)"><b>{{p.title}}</b><small>{{p.field||'方向待填写'}}</small></button><button class="text-button" @click="archiveProject(p.id,!p.archived)">{{p.archived?'恢复':'归档'}}</button></div><p v-if="!projects.length" class="muted">当前列表没有项目。</p></div></template>
    <template v-else-if="modal==='new'||modal==='settings'"><h2>{{modal==='new'?'新建研究项目':'项目设置'}}</h2><form class="record-form modal-form" @submit.prevent="submitProject"><label class="field-label" for="project-title">项目名称<input id="project-title" v-model="form.title" required maxlength="240"></label><label class="field-label" for="project-field">研究方向<input id="project-field" v-model="form.field" maxlength="1000"></label><button class="button primary" :disabled="busy">保存项目</button></form><button v-if="modal==='settings'" class="button" @click="exportProject()"><Icon name="download" :size="16"/>导出完整项目 JSON</button></template>
    <template v-else-if="modal==='library'"><span class="section-label">复用微信资料库</span><h2>选择论文或研究资料</h2><form @submit.prevent="searchLibrary" class="modal-search"><Icon name="search"/><input v-model="libraryQuery" aria-label="资料库搜索关键词" placeholder="输入标题、作者或主题"><button class="button" :disabled="libraryBusy">搜索</button></form><div class="search-results"><article v-for="m in libraryRows" :key="m.id" class="library-result"><h3>{{m.title}}</h3><p>{{m.summary?.slice(0,300)}}</p><small>{{m.collection}} · {{(m.tags||[]).join('、')}}</small><button class="button" :disabled="libraryBusy" @click="importMaterial(m)">导入阅读卡片</button></article><p v-if="!libraryRows.length" class="muted">搜索你的微信资料库，将方法、证据和摘要导入本项目。</p></div></template>
    <template v-else-if="modal==='more'"><h2>研究空间</h2><div class="more-menu"><button v-for="n in nav.filter(n=>!['overview','library','writing','reviews'].includes(n.id))" :key="n.id" @click="go(n.id)"><Icon :name="n.icon"/><span>{{n.label}}</span><Icon name="arrow" :size="16"/></button><button @click="archived=false;listProjects();modal='projects'"><Icon name="grid"/><span>切换 / 新建项目</span></button><button @click="openModal('settings')"><Icon name="settings"/><span>项目设置与导出</span></button></div></template>
    <p v-if="modalError" class="error-message" role="alert">{{modalError}}</p>
  </section></div>
</div>
</template>
